/// <summary>
/// gets HCMWorker for current userId
/// </summary>
/// <returns>HCMWorker</returns>
public static HcmWorker getHcmWorkerUser()
{
    HcmWorker hcmWorker;

    Info(curUserId());
    hcmWorker = HcmWorker::findByPerson(DirPersonUser::find(curUserId()).PersonParty);

    return hcmWorker;
}

/// <summary>
/// Gets the FormletterRemark text for the CustBalanceNote Report type
/// </summary>
/// <param name = "_languageId">language Id of report</param>
/// <param name = "_transDate">date of payments considered</param>
/// <param name = "_codeAccounting">accounting currency code</param>
/// <param name = "_balanceAccounting">accounting balance</param>
/// <param name = "_dueDate">date when payment is due</param>
/// <returns>string formatted from FormLetterRemark with provided parameters</returns>
public static str formLetterRemarks_Cust(LanguageId _languageId, TransDate _transDate, CurrencyCode _codeAccounting, Amount _balanceAccounting, TransDate _dueDate)
{
    FormLetterRemarks formLetterRemarks = FormLetterRemarks::find(_languageId, FormTextType::AVACustBalanceNote);
    str accountingBalance = strFmt('%1 %2', strUpr(_codeAccounting), num2Str(_balanceAccounting, 1, 2, 2, 1));

    str formLetterRemark = strFmt(formLetterRemarks.Txt, RetailENInfo::formatDatetimeData(_transDate, 'de'), accountingBalance, RetailENInfo::formatDatetimeData(_dueDate, 'de'));
    return formLetterRemark;
}

/// <summary>
